-- Generated by scripts/build-bob-creation-preparation-catalog.ts.
-- Install both matching Edge runtimes before activation. Existing manifests remain pinned.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
do $creation_preparation_publication$
declare specs jsonb:=$creation_preparation_spec$[{"key":"tools.edit_project_record","replacements":[["/design_intent/summary or /purpose","/design_intent/summary or /design_intent/purpose"],["or /choices/- without id","or /design_intent/choices/- without id"]],"patch":{}},{"key":"tools.search_material_catalog","replacements":[["Supply every required field, using null for unused nullable filters.","Supply every required field. Unused profile_code and profile_revision may be omitted or null; code supplies null. Typed property filters require both exact profile fields."]],"patch":{"parameters":{"type":"object","additionalProperties":false,"properties":{"entity":{"type":"string","enum":["categories","profiles","materials","parts"]},"query":{"type":["string","null"]},"categories":{"type":"array","maxItems":12,"uniqueItems":true,"items":{"type":"string"},"description":"Exact category codes, e.g. wood and sheet. Parent categories include descendants. Empty for vocabulary browsing."},"profile_code":{"type":["string","null"],"description":"Exact profile code, or null/omitted for an untyped search."},"profile_revision":{"type":["integer","null"]},"properties":{"type":"object","description":"Property keys come from read_material_catalog(profile). Each value has exactly value, unit, truth, parameter and note. Quantities are strings, not floats; decimal inputs have at most six decimals. Modern inch/tum uses unit=in and a separate value, e.g. 0.75, 0,75, 3/4, 1 1/2 or ¾. SQL converts exactly to mm before search/save; do not pre-round or put unit suffixes in value. Nominal trade sizes (2x4, R 1/2) belong in nominal_size text/aliases, NEVER in a numeric dimension; retain independently specified dimensions or explicit unknowns. A part may use value=null, truth=provided_spec and a named parameter; unknown requires a note. Search filters must be known, non-parameter values. A profile and exact revision are required for typed property filters.","additionalProperties":{"type":"object","additionalProperties":false,"properties":{"value":{"type":["string","boolean","null"]},"unit":{"type":["string","null"]},"truth":{"type":"string","enum":["provided_spec","estimated","unknown"]},"parameter":{"type":["string","null"]},"note":{"type":"string"}},"required":["value","unit","truth","parameter","note"]}},"after":{"type":["string","null"],"description":"Copy next_cursor or null."}},"required":["entity","query","categories","properties","after"]},"required_parameters":["entity","query","categories","properties","after"],"optional_parameters":["profile_code","profile_revision"]}},{"key":"tools.read_construction_draft","replacements":[["view=work collects governing","For a new Construction, use artifact_id:null, revision:null, ids:[] and view=work before authoring geometry; preparation reports the same design-readiness issues checked at save. view=work collects governing"]],"patch":{}},{"key":"bob.tools","replacements":[],"patch":{},"followups":[{"after_tool":"read_construction_draft","statuses":["ok"],"when":{"field":"creation_state","equals":"ready"},"tools":["save_construction_draft","search_material_catalog","read_material_catalog"]},{"after_tool":"read_construction_draft","statuses":["ok"],"when":{"field":"creation_state","equals":"needs_data"},"tools":["edit_project_record"]},{"after_tool":"read_construction_draft","statuses":["ok"],"when":{"field":"scoped_refinement_available","equals":true},"tools":["save_construction_draft"]},{"after_tool":"read_construction_draft","statuses":["ok"],"when":{"field":"creation_state","equals":"no_selected_solution"},"tools":["create_solution_alternative","select_solution_alternative","search_material_catalog","read_material_catalog"]}]}]$creation_preparation_spec$::jsonb;
 item jsonb; prior shared.ai_prompt_versions; definition jsonb; replacement jsonb; field text;
 next_version integer; version_uuid uuid; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 for item in select value from jsonb_array_elements(specs) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id
   where p.app='bob' and p.prompt_key=item->>'key' and p.retired_at is null for update of p;
  if not found then raise exception 'creation_preparation_contract_missing'; end if;
  if prior.metadata->>'creation_preparation_version'='1' then continue; end if;
  definition:=prior.definition||(item->'patch');
  for replacement in select value from jsonb_array_elements(item->'replacements') loop
   foreach field in array array['description','additional_description','card_description'] loop
    if definition ? field then definition:=jsonb_set(definition,array[field],to_jsonb(replace(definition->>field,replacement->>0,replacement->>1))); end if;
   end loop;
  end loop;
  if item ? 'followups' then
   if prior.metadata->>'construction_work_version' is distinct from '1' then raise exception 'creation_preparation_requires_construction_work'; end if;
   definition:=jsonb_set(definition,'{operation_followups}',(definition->'operation_followups')||(item->'followups'));
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,
    (prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','creation-preparation-v1','creation_preparation_version',1),
    prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(item->>'key',version_uuid);
 end loop;
 if activation<>'{}'::jsonb then perform shared.activate_ai_catalog('bob',activation); end if;
end $creation_preparation_publication$;
commit;
